import type {
  KpiOverviewBarChartPalette,
  KpiOverviewBarColorContext,
  KpiOverviewBarColorResolver,
} from '../types';

export function createDefaultBarColorResolver(
  palette: KpiOverviewBarChartPalette,
): KpiOverviewBarColorResolver {
  return ({
    label,
    index,
    stripedIndexes,
    highlightLabels,
  }: KpiOverviewBarColorContext) => {
    if (stripedIndexes.includes(index)) return palette.striped;
    if (highlightLabels.includes(label)) return palette.current;
    if (index === 0 && palette.lastYear) return palette.lastYear;
    return palette.default;
  };
}
